(()=>{
  'use strict';
  if(window.__QMES_MOBILE_SALES_DETAIL_20260904__) return;
  window.__QMES_MOBILE_SALES_DETAIL_20260904__=true;
  const clean=v=>String(v==null?'':v).replace(/\s+/g,' ').trim();
  const esc=v=>clean(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=v=>{const n=Number(String(v??'').replace(/[^0-9.+-]/g,''));return Number.isFinite(n)?n:0};
  const payload=r=>{let p=r&&r.payload;if(p&&typeof p==='object')return p;if(typeof p==='string'){try{return JSON.parse(p)}catch(_){}}return{}};
  async function api(path){const r=await fetch(path,{credentials:'same-origin',cache:'no-store'});const p=await r.json().catch(()=>null);if(r.status===401){location.replace('/mobile-login.html?mobile=1&v=20260904-sales-detail1');throw new Error('AUTH')}if(!r.ok||p?.success===false)throw new Error(p?.message||`HTTP ${r.status}`);return p?.data!==undefined?p.data:p}
  function injectStyle(){if(document.getElementById('qmes-mobile-sales-detail-style'))return;const s=document.createElement('style');s.id='qmes-mobile-sales-detail-style';s.textContent=`
    .title strong{color:#176da1!important;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px;cursor:pointer}.qsdm{position:fixed;inset:0;z-index:9999;display:none;align-items:flex-end;background:rgba(12,31,47,.42)}.qsdm.show{display:flex}.qsdm-card{width:min(100%,760px);max-height:95dvh;margin:0 auto;background:#f5f7f9;border-radius:18px 18px 0 0;overflow:hidden;box-shadow:0 -22px 60px rgba(13,35,53,.2)}.qsdm-head{display:flex;gap:10px;align-items:flex-start;padding:15px 14px;background:#fff;border-bottom:1px solid #dce4eb}.qsdm-head>div{min-width:0;flex:1}.qsdm-head strong{display:block;color:#173249;font-size:16px;font-weight:950}.qsdm-head span{display:block;margin-top:4px;color:#7f8e9c;font-size:8px;font-weight:750}.qsdm-close{width:36px;height:36px;border:1px solid #d8e1e8;border-radius:9px;background:#fff;color:#5e7183;font-size:20px}.qsdm-body{max-height:calc(95dvh - 68px);overflow:auto;padding:10px 10px calc(18px + env(safe-area-inset-bottom))}.qsdm-flow{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px;margin-bottom:9px}.qsdm-step{padding:8px 4px;border:1px solid #dce4eb;border-radius:9px;background:#fff;text-align:center}.qsdm-step b{display:block;color:#395269;font-size:7.6px;font-weight:950}.qsdm-step span{display:block;margin-top:4px;color:#8795a1;font-size:6.5px;font-weight:800}.qsdm-step.done{background:#eef9f1;border-color:#cde8d5}.qsdm-step.done b{color:#28794a}.qsdm-step.current{background:#edf6fb;border-color:#a7cee3}.qsdm-step.current b{color:#176da1}.qsdm-section{margin-top:8px;border:1px solid #dce4eb;border-radius:11px;background:#fff;overflow:hidden}.qsdm-section h3{margin:0;padding:10px 11px;border-bottom:1px solid #edf1f4;background:#f8fafb;color:#29445c;font-size:10px;font-weight:950}.qsdm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));padding:4px 10px 8px}.qsdm-field{min-width:0;padding:8px 4px;border-bottom:1px solid #eff2f4}.qsdm-field label{display:block;color:#929daa;font-size:6.8px;font-weight:850}.qsdm-field strong{display:block;margin-top:4px;color:#324b60;font-size:8.8px;font-weight:850;word-break:break-word}.qsdm-list{padding:5px 10px 8px}.qsdm-row{padding:8px 2px;border-bottom:1px solid #eef2f4}.qsdm-row:last-child{border-bottom:0}.qsdm-row b{display:block;color:#314b61;font-size:8.8px;font-weight:900}.qsdm-row span{display:block;margin-top:3px;color:#7f8d9a;font-size:7.3px;font-weight:750;line-height:1.45}.qsdm-empty{padding:18px 10px;text-align:center;color:#8694a0;font-size:8px;font-weight:750}.qsdm-loading{padding:35px 10px;text-align:center;color:#6f8293;font-size:9px;font-weight:850}.qsdm-status{display:inline-flex;padding:4px 7px;border-radius:999px;background:#eef2f5;color:#526577;font-size:7px;font-weight:950}.qsdm-status.ok{background:#e9f7ed;color:#287949}.qsdm-status.warn{background:#fff2dc;color:#9a6407}.qsdm-status.bad{background:#fde9ec;color:#aa3543}@media(min-width:700px){.qsdm-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
  `;document.head.appendChild(s)}
  function modal(){let m=document.getElementById('qmes-mobile-sales-detail');if(m)return m;m=document.createElement('div');m.id='qmes-mobile-sales-detail';m.className='qsdm';m.innerHTML='<section class="qsdm-card"><header class="qsdm-head"><div><strong id="qsdmTitle">수주 통합 상세</strong><span id="qsdmSub">-</span></div><button class="qsdm-close" type="button">×</button></header><div class="qsdm-body" id="qsdmBody"><div class="qsdm-loading">상세 정보를 불러오는 중입니다.</div></div></section>';document.body.appendChild(m);m.querySelector('.qsdm-close').onclick=()=>m.classList.remove('show');m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('show')});return m}
  function matchObj(obj,terms){try{const s=JSON.stringify(obj).toLowerCase();return terms.some(t=>t&&s.includes(t.toLowerCase()))}catch(_){return false}}
  function flatten(records,type){const out=[];(Array.isArray(records)?records:[]).forEach(r=>{const p=payload(r);if(p.deleted)return;if(type==='workorder'&&p.batch)out.push({...p.batch,_key:r.record_key||r.recordKey||'',_updated:r.updated_at||''});for(const k of ['rows','items','list','lots','inventory','stocks','data'])if(Array.isArray(p[k]))p[k].forEach(x=>out.push({...x,_key:r.record_key||r.recordKey||'',_updated:r.updated_at||''}))});return out}
  const first=(o,ks,f='-')=>{for(const k of ks){const v=clean(o&&o[k]);if(v)return v}return f};
  function statusTone(s){s=clean(s);if(/완료|합격|정상|납품/.test(s))return'ok';if(/위험|지연|불합격|차단/.test(s))return'bad';return'warn'}
  function field(label,value){return `<div class="qsdm-field"><label>${esc(label)}</label><strong>${esc(value||'-')}</strong></div>`}
  function listRows(items,formatter){return items.length?`<div class="qsdm-list">${items.map(formatter).join('')}</div>`:'<div class="qsdm-empty">연결된 정보가 없습니다.</div>'}
  async function openDetail(order){const m=modal(),body=m.querySelector('#qsdmBody');m.querySelector('#qsdmTitle').textContent=`${order.id||'수주'} 통합 상세`;m.querySelector('#qsdmSub').textContent=`${order.customer||'-'} · ${order.product||'-'}`;body.innerHTML='<div class="qsdm-loading">수주 관련 정보를 통합 조회 중입니다.</div>';m.classList.add('show');const terms=[clean(order.id),clean(order.po),clean(order.customer),clean(order.product)].filter(Boolean);
    try{const results=await Promise.allSettled([api('/api/qmes-sync/workorder'),api('/api/qmes-sync/pqc'),api('/api/qmes-sync/oqc'),api('/api/qmes-sync/inventory')]);const work=flatten(results[0].status==='fulfilled'?results[0].value:[],'workorder').filter(x=>matchObj(x,terms));const pqc=flatten(results[1].status==='fulfilled'?results[1].value:[],'pqc').filter(x=>matchObj(x,terms));const oqc=flatten(results[2].status==='fulfilled'?results[2].value:[],'oqc').filter(x=>matchObj(x,terms));const invRecords=Array.isArray(results[3].status==='fulfilled'?results[3].value:[])?results[3].value:[];const inv=flatten(invRecords,'inventory').filter(x=>matchObj(x,terms));const shipments=inv.filter(x=>/출하|ship|delivery|납품/i.test(JSON.stringify(x)));
      const workDone=work.length&&work.every(x=>/완료|종료/.test(first(x,['status','workStatus','productionStatus'],'')));const oqcDone=oqc.length&&oqc.some(x=>/합격|PASS|OK|완료/i.test(first(x,['judge','result','status'],'')));const shipDone=shipments.length&&shipments.some(x=>/완료|납품/.test(first(x,['status','shipping','deliveryStatus'],'')));const planDone=/반영완료|생산중|완료/.test(clean(order.plan));
      body.innerHTML=`<div class="qsdm-flow"><div class="qsdm-step done"><b>수주확정</b><span>${esc(order.id||'-')}</span></div><div class="qsdm-step ${planDone?'done':'current'}"><b>생산계획</b><span>${esc(order.plan||'계획대기')}</span></div><div class="qsdm-step ${workDone?'done':work.length?'current':''}"><b>작업/생산</b><span>${work.length}건</span></div><div class="qsdm-step ${oqcDone?'done':oqc.length?'current':''}"><b>OQC</b><span>${oqc.length}건</span></div><div class="qsdm-step ${shipDone?'done':shipments.length?'current':''}"><b>출하</b><span>${shipments.length}건</span></div></div>
      <section class="qsdm-section"><h3>수주 기본정보</h3><div class="qsdm-grid">${field('수주번호',order.id)}${field('수주일자',order.orderDate)}${field('고객사',order.customer)}${field('고객 PO',order.po)}${field('제품군',order.productGroup)}${field('제품명',order.product)}${field('수주량',`${num(order.qty).toLocaleString('ko-KR')} kg`)}${field('요청 납기일',order.due)}${field('긴급여부',order.urgent)}${field('생산구분',order.productionType)}${field('생산계획',order.plan)}${field('출하상태',order.shipping)}${field('비고',order.note)}</div></section>
      <section class="qsdm-section"><h3>작업지시 · 생산진행</h3>${listRows(work,(x)=>`<div class="qsdm-row"><b>${esc(first(x,['no','workOrderNo','lot','id'],'작업지시'))} <span class="qsdm-status ${statusTone(first(x,['status','workStatus','productionStatus'],''))}">${esc(first(x,['status','workStatus','productionStatus'],'-'))}</span></b><span>${esc(first(x,['product','productName','item'],order.product))} · 계획 ${esc(first(x,['plan','plannedQty','qty'],'-'))} · 실적 ${esc(first(x,['done','actualQty','productionQty'],'-'))}</span></div>`)}</section>
      <section class="qsdm-section"><h3>PQC 공정검사</h3>${listRows(pqc,(x)=>`<div class="qsdm-row"><b>${esc(first(x,['lot','groupId','id'],'PQC'))} <span class="qsdm-status ${statusTone(first(x,['judge','result','status'],''))}">${esc(first(x,['judge','result','status'],'-'))}</span></b><span>${esc(first(x,['check','item','name'],'검사항목'))} · ${esc(first(x,['value','measurement'],'-'))}</span></div>`)}</section>
      <section class="qsdm-section"><h3>OQC 출하검사</h3>${listRows(oqc,(x)=>`<div class="qsdm-row"><b>${esc(first(x,['lot','groupId','id'],'OQC'))} <span class="qsdm-status ${statusTone(first(x,['judge','result','status'],''))}">${esc(first(x,['judge','result','status'],'-'))}</span></b><span>${esc(first(x,['check','item','name'],'검사항목'))} · ${esc(first(x,['value','measurement'],'-'))}</span></div>`)}</section>
      <section class="qsdm-section"><h3>출하 · 납품정보</h3>${listRows(shipments,(x)=>`<div class="qsdm-row"><b>${esc(first(x,['shipNo','shippingNo','deliveryNo','id'],'출하'))} <span class="qsdm-status ${statusTone(first(x,['status','shipping','deliveryStatus'],''))}">${esc(first(x,['status','shipping','deliveryStatus'],'-'))}</span></b><span>LOT ${esc(first(x,['lot','finishedLot'],'-'))} · 수량 ${esc(first(x,['shipQty','qty','actualQty'],'-'))} · 일자 ${esc(first(x,['actualShipDate','shipDate','date'],'-'))}</span></div>`)}</section>`;
    }catch(e){if(e.message==='AUTH')return;body.innerHTML=`<div class="qsdm-empty">상세 정보를 불러오지 못했습니다.<br>${esc(e.message)}</div>`}}
  function findOrderFromCard(card){const id=clean(card.querySelector('.title strong')?.textContent);if(!id)return null;const fs=Array.from(card.querySelectorAll('.field'));const map={};fs.forEach(f=>{const k=clean(f.querySelector('label')?.textContent),v=clean(f.querySelector('span')?.textContent);map[k]=v});return{id,orderDate:map['수주일자'],customer:map['고객사'],po:map['고객 PO'],productGroup:map['제품군'],product:map['제품'],productionType:map['생산구분'],qty:map['수주량'],due:map['요청 납기일']||map['납기'],plan:map['생산계획'],shipping:map['출하상태'],note:map['비고']}}
  function bind(){injectStyle();document.addEventListener('click',e=>{const t=e.target.closest('.card .title strong');if(!t)return;const card=t.closest('.card');const order=findOrderFromCard(card);if(order)openDetail(order)})}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
})();